#include "PlantGrowthComponent.h"
#include "PlantDefinition.h"
UPlantGrowthComponent::UPlantGrowthComponent(){PrimaryComponentTick.bCanEverTick=false;}
void UPlantGrowthComponent::SetDefinition(UPlantDefinition* NewDef){Definition=NewDef;ResetPlant();}
void UPlantGrowthComponent::ResetPlant(){const int32 PreviousSeeds=PlantState.SeedCount;PlantState=FPlantState();PlantState.SeedCount=PreviousSeeds;PlantState.bIsAlive=true;PlantState.Stage=EGrowthStage::Seed;}
void UPlantGrowthComponent::SetStress(float W,float N,float Weed){PlantState.WaterStress=FMath::Clamp(W,0.f,1.f);PlantState.NutrientStress=FMath::Clamp(N,0.f,1.f);PlantState.WeedPressure=FMath::Clamp(Weed,0.f,1.f);}
float UPlantGrowthComponent::HarvestBiomass(){const float Out=PlantState.Biomass;PlantState.Biomass=0.f;PlantState.AccumulatedGDD=0.f;PlantState.Stage=EGrowthStage::Seed;PlantState.StageProgress=0.f;PlantState.bIsHarvestable=false;PlantState.bIsAlive=true;return Out;}
void UPlantGrowthComponent::UpdateDaily(float TempMax,float TempMin,float DeltaTime){if(!Definition||!PlantState.bIsAlive||DeltaTime<=0.f)return; const float Tavg=(TempMax+TempMin)*0.5f; float GDD=FMath::Min(Tavg,Definition->MaxTemperature)-Definition->BaseTemperature; GDD=FMath::Max(0.f,GDD)*DeltaTime; const float Ks=FMath::Clamp(PlantState.WaterStress,0.f,1.f),Kn=FMath::Clamp(PlantState.NutrientStress,0.f,1.f),Mw=FMath::Max(0.3f,1.f-PlantState.WeedPressure); PlantState.AccumulatedGDD+=GDD; PlantState.Stage=Definition->GetStageForGDD(PlantState.AccumulatedGDD); PlantState.StageProgress=Definition->GetStageProgress(PlantState.AccumulatedGDD); const float DailyWaterUse=5.f*Ks*DeltaTime; const float Gain=DailyWaterUse*Definition->WaterUseEfficiency*Kn*Mw; PlantState.Biomass=FMath::Clamp(PlantState.Biomass+Gain,0.f,Definition->MaxBiomass); PlantState.bIsHarvestable=PlantState.Stage==EGrowthStage::Maturity; if(PlantState.Stage==EGrowthStage::Maturity&&PlantState.Biomass>=Definition->MaxBiomass*.98f)PlantState.Stage=EGrowthStage::Senescence; }
